head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnIoFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 ioFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 ioFormat 속성을 설정하려는 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : date/date(숨김)/date(custom)/text Column 구성. setColumnIoFormat 을 Column ID 로 호출.
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column(숨김 포함) dDate(date/text·동작) / dHide(date·숨김) / dCustom(date/custom·미동작) / dText(text·미동작) / dTime(date/시분초·동작), 데이터 3행. columnInfo 파라미터를 인덱스가 아닌 Column ID 문자열로 호출.\n[절차] columnInfo(Column ID) 선택 -> (setColumnIoFormat 실행). date 컬럼(dDate, dTime) 셀 더블클릭 편집 후 포커스아웃하면 편집값(ioFormat)·표시값(displayFormat)이 자동 출력됨.\n[확인] Column ID 로 지목되어 date 컬럼만 동작 - dDate=ddMMyyyy(예 15012025)->표시 2025-01-15, dTime=HHmmSS(예 153045)->표시 15:30:45. dCustom/dText 는 미동작."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성 (date/date/date(custom)/text Column)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dDate" name="dDate" dataType="date"></w2:column>';
    strDlt += '<w2:column id="dHide" name="dHide" dataType="date"></w2:column>';
    strDlt += '<w2:column id="dCustom" name="dCustom" dataType="date"></w2:column>';
    strDlt += '<w2:column id="dText" name="dText" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dTime" name="dTime" dataType="date"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "dDate": "20250115", "dHide": "20250115", "dCustom": "20250115", "dText": "20250115", "dTime": "153045" },
        { "dDate": "20250220", "dHide": "20250220", "dCustom": "20250220", "dText": "20250220", "dTime": "093000" },
        { "dDate": "20250312", "dHide": "20250312", "dCustom": "20250312", "dText": "20250312", "dTime": "235959" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (date/date/date(custom)/text Column. body 컬럼 id 는 dataList 컬럼 id 와 동일해야 바인딩)
    //  columnInfo 파라미터를 (인덱스가 아닌) Column ID 문자열로 호출 -> dDate(동작)/dHide(숨김,동작)/dCustom(custom,미동작)/dText(text,미동작)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:220px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnIoFormat 테스트 그리드 (Column ID 호출)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" inputType="text" id="h0" value="dDate(date/text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h1" value="dHide(date/숨김)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="h2" value="dCustom(date/custom)"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h3" value="dText(text)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h4" value="dTime(date/시분초)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    // dDate : date + text -> Column ID 호출 동작 대상 (초기 displayFormat=yyyy.MM.dd -> yyyy-MM-dd 로 변경)
    strTarget += '<w2:column width="140" inputType="text" dataType="date" displayFormat="yyyy.MM.dd" id="dDate" dataList="dDate"></w2:column>';
    // dHide : date 숨김(setColumnVisible(1,false)) -> Column ID 로는 숨김 Column 도 지목 가능
    strTarget += '<w2:column width="120" inputType="text" dataType="date" displayFormat="yyyy.MM.dd" id="dHide" dataList="dHide"></w2:column>';
    // dCustom : date + custom -> 전제 미충족(inputType=custom) -> 미동작
    strTarget += '<w2:column width="140" inputType="custom" dataType="date" displayFormat="yyyy.MM.dd" id="dCustom" dataList="dCustom"></w2:column>';
    // dText : text -> 전제 미충족(dataType!=date) -> 미동작
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="dText" dataList="dText"></w2:column>';
    // dTime : date + 시분초(time) 데이터 -> Column ID 'dTime' 호출 시 HHmmSS / HH:mm:SS 로 시분초 정상 적용
    strTarget += '<w2:column width="130" inputType="text" dataType="date" displayFormat="HH:mm:SS" id="dTime" dataList="dTime"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // dHide(인덱스 1) 숨김 -> Column ID 로 숨김 Column 도 지목 가능함을 확인
    target1.setColumnVisible(1, false);
}



// [실행] setColumnIoFormat : columnInfo 파라미터에 (인덱스가 아닌) Column ID 문자열을 전달하여 ioFormat / displayFormat 을 설정한다.
//  - dDate -> ioFormat="ddMMyyyy"(편집포맷), dateMask="yyyy-MM-dd"(displayFormat 표시포맷)
scwin.btn_setColumnIoFormat_onclick = function () {
    // columnInfo 파라미터 : Column ID 문자열
    let colID = par_columnInfo.getValue();
    // dTime(시분초 컬럼) 은 HHmmSS / HH:mm:SS, 그 외 date 컬럼은 ddMMyyyy / yyyy-MM-dd 적용
    let ioFormat = (colID === 'dTime') ? "HHmmSS" : "ddMMyyyy";
    let dateMask = (colID === 'dTime') ? "HH:mm:SS" : "yyyy-MM-dd";

    // columnInfo 파라미터에 Column ID 문자열을 전달하여 호출
    target1.setColumnIoFormat(colID, ioFormat, dateMask);

    let colIndex = target1.getColumnIndex(colID);
    let opt = target1.getCellInfo(colIndex).options;
    let arr = scwin.collectColText(colIndex);

    let msg = "setColumnIoFormat('" + colID + "', '" + ioFormat + "', '" + dateMask + "')";
    msg += "\n[속성] ioFormat='" + opt.ioFormat + "' / displayFormat='" + opt.displayFormat + "'";
    msg += "\n[표시값] " + arr.join(', ');
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// 해당 Column 의 모든 Row 화면 표시값(td.textContent) 수집
scwin.collectColText = function (colIndex) {
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + colIndex + "']");
        arr.push(td ? td.textContent.trim() : '');
    }
    return arr;
}

// [이벤트] 셀을 직접 편집 -> 포커스 아웃(onafteredit) 하는 실제 인터랙션마다 편집값(ioFormat)/표시값(displayFormat) 자동 출력
scwin.target1_onbeforeedit = function (row, col, value) {
    scwin._editIoValue = value;   // 편집 입력창 표시값(ioFormat) 보관(참고용)
};
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';
    let msg = "편집->포커스아웃 [" + colID + "] (" + row + "," + col + ")";
    msg += "\n[편집값(ioFormat)] " + value;
    msg += "\n[표시값(displayFormat)] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
